let assertions=0;for(const row of cases){const {calculate}=require(path.join(root,'tools',row.slug+'.js'));const r=calculate(row.values);assert.ok(r.text.includes(row.expected),row.slug+' known result');assert.equal(typeof r.value,'string');assert.throws(()=>calculate(row.invalid),undefined,row.slug+' invalid input');const html=fs.readFileSync(path.join(root,'tools',row.slug+'.html'),'utf8');assert.equal((html.match(/src="\/ad-banner-isolated\.js\?v=20261027-banner"/g)||[]).length,1,row.slug+' ad');assert.ok(!/<button[^>]*>[^<]*(예시|샘플)/.test(html),row.slug+' no example buttons');assertions+=5;}
const run=(slug,v)=>require(path.join(root,'tools',slug+'.js')).calculate(v);
assert.equal(run('json-path-extractor',{source:'{"a/b":{"~x":[null,false]}}',path:'/a~1b/~0x/1'}).text,'false');
assert.equal(run('json-path-extractor',{source:'{"__proto__":{"x":1}}',path:'/__proto__/x'}).text,'1');
assert.throws(()=>run('json-path-extractor',{source:'[]',path:'/00'}));
assert.equal(run('json-diff',{before:'{"x":1,"y":{"a":2,"b":3}}',after:'{"y":{"b":3,"a":2},"x":1}'}).text,'차이 없음');
assert.equal(run('json-diff',{before:'[]',after:'{}'}).value,'1개 차이');
assert.deepEqual(JSON.parse(run('json-flattener',{source:'{"a/b":1,"a":{"b":2},"~":[],"":{}}'}).text),{'/a~1b':1,'/a/b':2,'/~0':[],'/':{}});
assert.match(run('json-to-typescript',{source:'{"a-b":[1,"x",null],"empty":[]}',name:'Data'}).text,/number \| string \| null/);
assert.throws(()=>run('json-to-typescript',{source:'{}',name:'string'}));
for(const name of ['for','keyof','infer','readonly','namespace','declare','async'])assert.throws(()=>run('json-to-typescript',{source:'{}',name}));
for(const source of ['{"x":1.0000000000000001}','{"x":1e-400}','{"x":1,"x":2}','{"x":{"y":1,"y":2}}'])assert.throws(()=>run('json-flattener',{source}));
assert.equal(run('json-flattener',{source:'{"a":[1,2,3],"b":{"c":0.1,"d":1e-10}}'}).value,'5개 경로');
assert.throws(()=>run('ini-json-converter',{source:'{"a":1}',mode:'json'}));
const iniJson={name:'  x # ; = ',server:{host:'localhost',password:'"\n\t'}};assert.deepEqual(JSON.parse(run('ini-json-converter',{source:run('ini-json-converter',{source:JSON.stringify(iniJson),mode:'json'}).text,mode:'ini'}).text),iniJson);
assert.throws(()=>run('ini-json-converter',{source:'x=y\n[x]\na=b',mode:'ini'}));
const raw='한글 😀 " \ \n';assert.equal(run('json-string-escape',{source:run('json-string-escape',{source:raw,mode:'encode'}).text,mode:'decode'}).text,raw);
assert.equal(run('utf8-hex-converter',{source:run('utf8-hex-converter',{source:'\uFEFF하루😀',mode:'encode'}).text,mode:'decode'}).text,'\uFEFF하루😀');
assert.throws(()=>run('utf8-hex-converter',{source:'ED A0 80',mode:'decode'}));
assert.throws(()=>run('utf8-hex-converter',{source:'\uD800',mode:'encode'}));
assert.equal(run('text-list-comparison',{a:' a \na\n',b:'a',mode:'intersection',space:'exact'}).text,'a');
assert.equal(run('text-list-comparison',{a:' a \na\n',b:'a',mode:'intersection',space:'trim'}).value,'1개 항목');
assert.equal(run('text-column-extractor',{source:'a\tb\tc\nx',columns:'3,1,3'}).text,'c\ta\n\tx');
assert.equal(run('text-prefix-suffix',{source:' x \n\ny\n',prefix:'[',suffix:']',empty:'skip'}).text,'[ x ]\n\n[y]\n');
assert.equal(run('text-numbering',{source:'a\n\nb\n',start:'0',step:'2',separator:':',empty:'skip'}).text,'0:a\n\n2:b\n');
assert.equal(run('text-chunk-splitter',{source:'😀가😺나',mode:'characters',size:'2'}).text,'[1]\n😀가\n\n[2]\n😺나');
assert.equal(run('text-transpose',{source:'a\tb\nc'}).text,'a\tc\nb\t');
const url=new URL(run('url-builder',{base:'https://example.com/?a=1',params:'a\t2\nq\t한 글&=',fragment:'hello world',mode:'append'}).text);assert.deepEqual(url.searchParams.getAll('a'),['1','2']);assert.equal(url.searchParams.get('q'),'한 글&=');assert.equal(url.hash,'#hello%20world');
assert.throws(()=>run('url-builder',{base:'https://u:p@example.com',params:'',fragment:'',mode:'append'}));
for(const literal of ['a+b (test).','[a-z] / \n','😀하루-한글','1foo','\uD800']){const escaped=run('regex-escape-generator',{source:literal}).text;assert.equal(new RegExp('^(?:'+escaped+')$','u').test(literal),true);}
assert.throws(()=>run('cron-expression-builder',{minute:'*/0',hour:'0',day:'*',month:'*',weekday:'*'}));
assert.throws(()=>run('cron-expression-builder',{minute:'*',hour:'0',day:'*',month:'*',weekday:'5-1'}));
assert.equal(run('cron-expression-builder',{minute:'0,30',hour:'1-5/2',day:'1',month:'1-12',weekday:'0,7'}).text,'0,30 1-5/2 1 1-12 0,7');
assert.match(run('css-grid-generator',{mode:'responsive',gap:'0',minimum:'200',columns:''}).text,/minmax\(min\(200px, 100%\), 1fr\)/);
assert.equal(run('css-clamp-generator',{minimum:'0',maximum:'100',from:'400',to:'1400'}).text,'clamp(0px, calc(-40px + 10vw), 100px)');
assert.equal(run('morse-code-converter',{source:run('morse-code-converter',{source:'Hello, world! 123',mode:'encode'}).text,mode:'decode'}).text,'HELLO, WORLD! 123');
assert.throws(()=>run('morse-code-converter',{source:'......',mode:'decode'}));
assert.throws(()=>run('morse-code-converter',{source:'/ ...',mode:'decode'}));
